"""Snap span times to a fixed step and label the results."""

from hourglass.models import Span


def check_step(step):
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour: {step}"
        )


def snap(minute, step):
    return (minute + step // 2) // step * step


def clock(minute):
    hours, mins = divmod(minute, 60)
    return f"{hours:02d}:{mins:02d}"


def label_one(span, step):
    start = snap(span.start, step)
    stop = snap(span.end, step)
    hours, mins = divmod(Span(start, stop).minutes, 60)
    return (
        f"{clock(start)}-{clock(stop)} ({hours}h {mins}m)"
    )


def label_spans(spans, step):
    check_step(step)
    return [label_one(span, step) for span in spans]

