import unittest

from hourglass.models import Span
from hourglass.rounding import label_spans


class LabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 12)]
        self.assertEqual(
            label_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [Span(8, 82)]
        self.assertEqual(
            label_spans(spans, 15), ["00:15-01:15 (1h 0m)"]
        )

    def test_empty(self):
        self.assertEqual(label_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                label_spans([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
